// BST Search
function search(root, target) {
  if (root === null) return null;
  if (root.val === target) return root;
  if (target < root.val) return search(root.left, target);
  return search(root.right, target);
}

// BST Validation with min/max range
function isValidBST(root) {
  function validate(node, min, max) {
    if (node === null) return true;
    if (min !== null && node.val <= min) return false;
    if (max !== null && node.val >= max) return false;
    return validate(node.left, min, node.val) &&
           validate(node.right, node.val, max);
  }
  return validate(root, null, null);
}

// Kth smallest in BST (inorder counting)
function kthSmallest(root, k) {
  let count = 0;
  let result = null;

  function inorder(node) {
    if (node === null || result !== null) return;
    inorder(node.left);
    count++;
    if (count === k) { result = node.val; return; }
    inorder(node.right);
  }

  inorder(root);
  return result;
}

// Ordered-set style query: count of elements <= x, using subtree-size augmentation
// (assumes each node also stores node.size = 1 + size(left) + size(right))
function countLessOrEqual(root, x) {
  let count = 0;
  let node = root;
  while (node !== null) {
    if (node.val <= x) {
      count += 1 + (node.left ? node.left.size : 0);  // this node + its whole left subtree qualify
      node = node.right;
    } else {
      node = node.left;
    }
  }
  return count;
}
